### Mutators config structure

Source: https://github.com/infection/infection/blob/master/resources/schema.json

Defines the mutators object with profiles (@arithmetic, @boolean, etc.), individual mutators (Plus, Minus, etc.), global-ignore/global-ignoreSourceCodeByRegex, and the default-mutator-config (boolean or object with ignore/ignoreSourceCodeByRegex)

```json
"mutators": {
    "type": "object",
    "additionalProperties": false,
    "patternProperties": {
        "^[\\w]+(?:\\\\[\\w]+){1,}$": { "$ref": "#/definitions/default-mutator-config" }
    },
    "description": "Contains the settings for different mutations and profiles",
    "properties": {
        "global-ignore": {
            "type": "array",
            "uniqueItems": true,
            "items": {
                "type": "string"
            }
        },
        "global-ignoreSourceCodeByRegex": {
            "type": "array",
            "uniqueItems": true,
            "items": {
                "type": "string",
                "format": "regex"
            }
        },
        "@arithmetic": { "$ref": "#/definitions/default-mutator-config" },
        "@boolean": { "$ref": "#/definitions/default-mutator-config" },
        "@default": { "$ref": "#/definitions/default-mutator-config" },
        "Plus": { "$ref": "#/definitions/default-mutator-config" }
    }
}
```

